async fn sequential_agent_rejects_resolutions() {
    let runs = Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let r = runs.clone();
    let child = MockAgent::new("child", move |_| {
        r.fetch_add(1, Ordering::SeqCst);
        msg_and_complete("child", "ran", 0)
    });
